  1→import { tmpdir } from "node:os";
  2→import { join } from "node:path";
  3→import { readFileSync, existsSync, unlinkSync } from "node:fs";
  4→import { randomUUID } from "node:crypto";
  5→import type { AgentConfig, AgentId, AgentResponse, ExecutionOptions } from "./types.js";
  6→import { BaseAgent } from "./base-agent.js";
  7→import { spawnAgent, type SpawnOptions } from "../orchestrator/executor.js";
  8→import { logger } from "../utils/logger.js";
  9→
 10→export class CodexAgent extends BaseAgent {
 11→	readonly id: AgentId = "codex";
 12→	readonly displayName = "Codex";
 13→	readonly cliCommand = "codex";
 14→
 15→	constructor(config: AgentConfig) {
 16→		super(config);
 17→	}
 18→
 19→	override async execute(options: ExecutionOptions): Promise<AgentResponse> {
 20→		const model = options.model ?? this.getDefaultModel();
 21→		const outputFile = join(tmpdir(), `codex-output-${randomUUID()}.txt`);
 22→
 23→		const analysisLevel = options.analysisLevel ?? this.config.defaultAnalysisLevel ?? "medium";
 24→
 25→		const args = [
 26→			"exec",
 27→			"--model",
 28→			model,
 29→			"-c",
 30→			`model_reasoning_effort=${analysisLevel}`,
 31→			"--sandbox",
 32→			"read-only",
 33→			"--output-last-message",
 34→			outputFile,
 35→			"-",
 36→		];
 37→
 38→		logger.info(`Executing Codex with model ${model}, analysis level ${analysisLevel}`);
 39→
 40→		const result = await spawnAgent({
 41→			command: this.cliCommand,
 42→			args,
 43→			timeout: options.timeout,
 44→			cwd: options.cwd,
 45→			stdin: options.context ? `${options.context}\n\n${options.prompt}` : options.prompt,
 46→		});
 47→
 48→		if (result.timedOut) {
 49→			this.cleanupFile(outputFile);
 50→			return {
 51→				agent: this.id,
 52→				model,
 53→				content: "",
 54→				durationMs: result.durationMs,
 55→				exitCode: 124,
 56→				error: `Timed out after ${options.timeout ?? 120000}ms`,
 57→			};
 58→		}
 59→
 60→		// Try to read from output file first, fallback to stdout
 61→		let content = "";
 62→		if (existsSync(outputFile)) {
 63→			try {
 64→				content = readFileSync(outputFile, "utf-8").trim();
 65→			} catch {
 66→				content = result.stdout.trim();
 67→			}
 68→			this.cleanupFile(outputFile);
 69→		} else {
 70→			content = result.stdout.trim();
 71→		}
 72→
 73→		return {
 74→			agent: this.id,
 75→			model,
 76→			content,
 77→			durationMs: result.durationMs,
 78→			exitCode: result.exitCode,
 79→			error: result.exitCode !== 0 ? result.stderr || `Exit code: ${result.exitCode}` : undefined,
 80→		};
 81→	}
 82→
 83→	protected buildSpawnOptions(options: ExecutionOptions, model: string): SpawnOptions {
 84→		// Not used directly - execute() is overridden
 85→		return {
 86→			command: this.cliCommand,
 87→			args: ["exec", "-", "--model", model, "--sandbox", "read-only"],
 88→			timeout: options.timeout,
 89→			cwd: options.cwd,
 90→			stdin: options.prompt,
 91→		};
 92→	}
 93→
 94→	private cleanupFile(path: string): void {
 95→		try {
 96→			if (existsSync(path)) unlinkSync(path);
 97→		} catch {
 98→			// Ignore cleanup errors
 99→		}
100→	}
101→}
102→

